#include "KS/SRC/entity_shared.h"

typedef unsigned int u_int;

enum WaveMarkerEnum
{
  WAVE_MarkerInvalid = -1,
  WAVE_MarkerHandDrag = 39
};

enum WaveRegionEnum
{
  WAVE_REGION_DUMMY
};

template <int n> struct SplineCoeffs
{
  float a[n], b[n], c[n], d[n];
};

typedef struct
{
  SplineCoeffs<16> y, z;
} WaveProfileCoeffs;

struct WavePositionHint
{
  float x, z;
  float xprofile;
  u_int xcell, zcell;
  u_int xgrid, zgrid;
  WaveProfileCoeffs wpc;
};

extern float WAVE_ToleranceDefaultD, WAVE_ToleranceDefaultZ;
struct WaveTolerance
{
  float dthresh;
  float zthresh;

  WaveTolerance(void) {dthresh = WAVE_ToleranceDefaultD; zthresh = WAVE_ToleranceDefaultZ;}
  WaveTolerance(float d, float z) {dthresh = d; zthresh = z;}
};

class CollideCallStruct
{
public:
  CollideCallStruct (const vector3d& pos, vector3d *n, vector3d *c, WaveRegionEnum *r, WavePositionHint *h)
    { position = pos; normal = n; current = c; region = r; hint = h;}

  vector3d position;
  vector3d *normal;
  vector3d *current;
  WaveRegionEnum *region;
  WavePositionHint *hint;
  WaveTolerance tolerance;
};

void WAVE_HintFromMarker(WaveMarkerEnum markernum, WavePositionHint *hint);
bool WAVE_CheckCollision (CollideCallStruct & cs, bool hint_valid, bool y_valid, bool near_match, bool limitgiven = false, WaveMarkerEnum frontlimit = WAVE_MarkerInvalid, WaveMarkerEnum backlimit = WAVE_MarkerInvalid);

inline float dot (const vector3d& v1, const vector3d& v2)
{
  return v1.x*v2.x + v1.y*v2.y + v1.z*v2.z;
}

class trail
{
public:
  bool hand_underwater (entity *hand, vector3d& pos) const;
};

bool trail::hand_underwater (entity *hand, vector3d& pos) const
{
  WavePositionHint hint;
  WAVE_HintFromMarker(WAVE_MarkerHandDrag, &hint);

  vector3d normal;
  CollideCallStruct collide (hand->get_abs_position (), &normal, NULL, NULL, &hint);
  WAVE_CheckCollision (collide, true, true, false);
  pos = collide.position;

  // calculate the distance from the hand to the surface of the water
  vector3d dist = collide.position - hand->get_abs_position ();

  if (dot (dist, normal) > 0)
    return true;
  else
    return false;
}
